C中结构体之指针与数组#include &lt;iostream&gt;#include &lt;conio.h&gt;#include &lt;stdlib.h&gt;#include &lt;string.h&gt;#include &lt;stdio.h&gt;using namespace std;// 今天描述结构体中的指针和数组typedef struct _Player&#123;    int level;    char name[20];&#125; Player, *PPplayer;// 上面这个第一个结构体里面成员在内存中是连续的void fun1()&#123;    PPplayer p1 = (PPplayer)malloc(sizeof(Player)); // 为p1申请内存    memset(p1, 0, sizeof(Player));                  // 初始化    p1-&gt;level = 1;    strcpy(p1-&gt;name, &quot;张三&quot;);    cout &lt;&lt; &quot;p1-&gt;level:&quot; &lt;&lt; p1-&gt;level &lt;&lt; endl;    cout &lt;&lt; &quot;p1-&gt;name:&quot; &lt;&lt; p1-&gt;name &lt;&lt; endl;    free(p1);    p1 = NULL;&#125;typedef struct _Player2&#123;    int level;    char *name; // name是一个指针&#125; Player2, *PPplayer2;// 上面这个结构体里面成员在内存中是不连续的void fun2()&#123;    PPplayer2 p2 = (PPplayer2)malloc(sizeof(Player2)); // 为p2申请内存    memset(p2, 0, sizeof(Player2));                    // 初始化    p2-&gt;level = 1;    p2-&gt;name = (char *)malloc(strlen(&quot;1angx&quot;) + 1); // 为name申请内存,这里用了strlen()函数，最后的\x00的大小没有加上去，所以要加个1    memset(p2-&gt;name, 0, 20);                        // 初始化    strcpy(p2-&gt;name, &quot;1angx&quot;);    cout &lt;&lt; &quot;p2-&gt;level:&quot; &lt;&lt; p2-&gt;level &lt;&lt; endl;    cout &lt;&lt; &quot;p2-&gt;name:&quot; &lt;&lt; p2-&gt;name &lt;&lt; endl;    // free(p2-&gt;name);    free(p2);    p2 = NULL;&#125;typedef struct _Player3&#123;    int level;    char name[1]; // 这里给name的大小为1个字节，我们等会会在fun3函数中说明为何&#125; Player3, *PPplayer3;void fun3()&#123;    PPplayer3 p3 = (PPplayer3)malloc(sizeof(Player3) + strlen(&quot;1angx&quot;)); // 为p3申请内存，同时加上我们的name的大小，这里因为我们数组的大小是1所以不需要再加上1了    memset(p3, 0, sizeof(Player3) + strlen(&quot;1angx&quot;));                    // 初始化    p3-&gt;level = 1;    strcpy(p3-&gt;name, &quot;1angx&quot;); // 这里我们直接给name赋值是不是越界访问了，确实是，但是由于在结构体中内存是连续的，name在结构体中，我们的结构体的大小足够大，且level name的内存是连续的    cout &lt;&lt; &quot;p3-&gt;level:&quot; &lt;&lt; p3-&gt;level &lt;&lt; endl;    cout &lt;&lt; &quot;p3-&gt;name:&quot; &lt;&lt; p3-&gt;name &lt;&lt; endl;    free(p3);    p3 = NULL;    puts(&quot;fun3中，我们就实现了内存连续，且大小为动态的name&quot;);    puts(&quot;我们通过‘越界访问’实现了这一要求&quot;);&#125;int main()&#123;    fun1(); // fun1中确实是利用数组实现了角色名称的创建，但是大小是固定的，不能动态改变    putchar(&#x27;
&#x27;);    fun2(); // fun2中利用指针实现了角色名称的创建，大小是动态的，但是内存是不连续的    putchar(&#x27;
&#x27;);    puts(&quot;那我们怎么实现大小是动态的，其在内存空间中的大小也是动态的？
